recipes.code:
{
  "inputs": [
    {
      "id": "snapforge-api-key",
      "type": "promptString",
      "description": "SnapForge API key. Optional: without it, call the snapforge_signup tool once to get a free key (100 renders/month)",
      "password": true
    }
  ],
  "servers": {
    "snapforge": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "snapforge-mcp@1.3.0"
      ],
      "env": {
        "SNAPFORGE_API_KEY": "${input:snapforge-api-key}"
      }
    }
  }
}
